    # path_tuple as a secondary key makes the lexicographically smallest path win ties.
    heap: list = [(-float("inf"), (src,), src)]
    while heap:
        neg_load, path_tuple, node = heapq.heappop(heap)
        load = -neg_load
        # Skip stale entries (a better load or a better path was already recorded).
        if load < best_load.get(node, -1):
            continue
        if load == best_load[node] and path_tuple > tuple(best_path[node]):
            continue
        if node == dst:
            return int(load), list(best_path[node])
